// P06 movement against the oracle in real gameplay: the original game runs in jsnes with every P06
// routine spliced to its JS port (tests/game/p06-splice.mjs); RAM and SRAM must equal the pure
// original in every frame. The routines of other packages that the ports call run as their JS ports
// or, while still stubs, as original code. Skipped without roms/zelda.nes or jsnes.
// The movies are generated by tests/game/p06-make-movies.mjs.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { hasRom, ROOT } from '../core/helpers.mjs';

const canRun = hasRom && existsSync(join(ROOT, 'tools/oracle/node_modules/jsnes/src/index.js'));
const skip = !canRun && 'needs roms/zelda.nes and tools/oracle jsnes';
const MOVIES = join(ROOT, 'tests/oracle/movies');

let S, loadMovie, V;
if (canRun) {
  S = await import('./p06-splice.mjs');
  ({ loadMovie } = await import('../../tools/oracle/lib/movie.mjs'));
  V = await import('../../src/core/vars.js');
}

for (const name of ['walk-first-screens', 'p06-ow-cave-walls', 'p06-to-level1']) {
  test(`P06 spliced into the original: ${name} has RAM/SRAM diff 0`, { skip }, async (t) => {
    const r = await S.spliceCompare(loadMovie(join(MOVIES, `${name}.zmv`)));
    t.diagnostic(`frames ${r.frames}; JS calls ${JSON.stringify(r.calls)}`);
    assert.equal(r.divergence, null, r.divergence && `frame ${r.divergence.frame}:\n${r.divergence.diffs.join('\n')}`);
    assert.ok(r.calls.Walker_Move > 1000, 'Walker_Move ran as JS');
    const expectPath = join(MOVIES, `${name}.expect.json`);
    if (!name.startsWith('p06-') || !existsSync(expectPath)) return;
    const expect = JSON.parse(readFileSync(expectPath, 'utf8'));
    for (const [v, values] of Object.entries(expect.reaches)) {
      for (const value of [].concat(values)) {
        assert.ok(r.original.some((f) => f.ram[V[v]] === value), `${name}: ${v} never reaches ${value}`);
      }
    }
    if (name === 'p06-ow-cave-walls') {
      assert.ok(r.original.some((f) => f.ram[V.ObjShoveDir] !== 0), 'Link is knocked back');
      assert.ok(r.original.some((f) => f.ram[V.ObjShoveDir + 1] !== 0 || f.ram[V.ObjShoveDir + 2] !== 0), 'a monster is shoved');
    }
    if (name === 'p06-to-level1') assert.ok(r.original.some((f) => f.ram[V.DoorwayDir] !== 0), 'Link in a doorway');
  });
}
